// wp.codeEditor is missing when the user turned syntax highlighting off; the textarea then stays a plain field.
if (document.getElementById("custom_template_input") && window.wp && wp.codeEditor) {
    // Get WordPress CodeMirror settings
    const editorSettings = wp.codeEditor.defaultSettings.codemirror;

    // Override some settings
    editorSettings.mode = 'text/html';
    editorSettings.lineNumbers = true;
    editorSettings.lineWrapping = true;

    // Initialize the editor
    const editor = wp.codeEditor.initialize(document.getElementById("custom_template_input"), {
        codemirror: editorSettings
    }).codemirror;

    // Your existing change handler
    editor.on("change", function () {
        document.getElementById("custom_template_input").value = editor.getValue();
    });

    // Your placeholder insertion function
    function insertPlaceholder(placeholder) {
        const cursor = editor.getCursor();
        editor.replaceRange(placeholder, cursor);
        editor.focus();
    }
}

// form manage script show & hide custom template
document.addEventListener("DOMContentLoaded", function () {
    const checkbox = document.querySelector('input[name="dapfforwc_options[use_custom_template]"]');

    // Function to show or hide the closest <tr> with the .custom_template_code class
    function toggleTemplateRow() {
        let closestTr = document.querySelector(".custom_template_code");

        if (closestTr) { closestTr = closestTr.closest('tr'); }

        // Check if the next sibling has the class 'custom_template_code'
        if (closestTr) {
            if (checkbox.checked) {
                closestTr.style.display = ''; // Show the row
            } else {
                closestTr.style.display = 'none'; // Hide the row
            }
        }
    }
    // Event listener for checkbox change
    if (checkbox) {
        checkbox.addEventListener('change', toggleTemplateRow);
    }

    // Initialize the state on page load
    toggleTemplateRow();
});

// loading effect popup
document.addEventListener('DOMContentLoaded', function () {
    const customizeLoaderLink = document.getElementById('customize_loader');
    const popup = document.getElementById('custom-loading-popup');
    const closePopup = document.querySelector('.close-popup');
    const saveEffectButton = document.getElementById('save-effect');
    let selectedEffect = null;

    if (customizeLoaderLink) {
        customizeLoaderLink.addEventListener('click', function (e) {
            e.preventDefault();
            popup.style.display = 'flex';
        });
    }

    if (closePopup) {
        closePopup.addEventListener('click', function () {
            popup.style.display = 'none';
        });
    }

    document.querySelectorAll('.loading-option').forEach(option => {
        option.addEventListener('click', function () {
            const html = this.getAttribute('data-html');
            const css = this.getAttribute('data-css');
            document.getElementById('loader_html').value = html;
            document.getElementById('loader_css').value = css;
            // Remove selected class from all options
            document.querySelectorAll('.loading-option').forEach(opt => opt.classList.remove('selected'));
            // Add selected class to the clicked option
            this.classList.add('selected');
            // Store the selected effect value
            selectedEffect = this.getAttribute('data-value');
        });
    });
});



document.addEventListener('DOMContentLoaded', function () {
    const checkbox = document.querySelector('input[name="dapfforwc_seo_permalinks_options[enable_seo]"]');
    const secondTable = document.querySelectorAll('table.form-table')[1];

    function toggleInputs() {
        if (!secondTable) return;
        const inputsAndSelects = secondTable.querySelectorAll('select');
        const isChecked = checkbox.checked;

        inputsAndSelects.forEach(input => {
            input.disabled = !isChecked;
        });
    }

    // Initial check
    if (secondTable && checkbox) {
        toggleInputs();
        // Listen for changes
        checkbox.addEventListener('change', toggleInputs);
    }
});


jQuery(document).ready(function ($) {
    // Initialize Select2 on all select elements with the class 'plugincy_select2'
    // Select2 does not accept a function as placeholder; give each select its own data-placeholder text.
    $('.plugincy_select2').each(function () {
        $(this).select2({
            placeholder: $(this).data('placeholder') || '',
            width: 'resolve',
            allowClear: true,
        });
    });
});



function copyToClipboard(event, shortcode) {
    const button = event && event.currentTarget;
    if (!button) {
        return;
    }
    const l10n = window.dapfforwcAdminL10n || {};
    // Remember the untouched button once, so a second click during the "Copied" state cannot make "Copied" the original.
    if (button.dataset.copyOriginalHtml === undefined) {
        button.dataset.copyOriginalHtml = button.innerHTML;
    }
    const originalHtml = button.dataset.copyOriginalHtml;
    const hasText = !!button.querySelector('.btn-text');

    // Fallback for browsers/contexts without the async clipboard API; reports whether the copy really happened.
    function fallbackCopy(text) {
        const textArea = document.createElement('textarea');
        textArea.value = text;
        textArea.style.position = 'fixed';
        textArea.style.left = '-999999px';
        textArea.style.top = '-999999px';
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();

        let copied = false;
        try {
            copied = document.execCommand('copy');
        } catch (err) {
            copied = false;
        }
        textArea.remove();
        return copied;
    }

    const copyWithFallback = function () {
        return fallbackCopy(shortcode) ? Promise.resolve() : Promise.reject(new Error('copy failed'));
    };
    const copyPromise = navigator.clipboard && navigator.clipboard.writeText
        ? navigator.clipboard.writeText(shortcode).catch(copyWithFallback)
        : copyWithFallback();

    copyPromise.then(() => {
        clearTimeout(button._dapfforwcCopyTimer);
        button.classList.add('copied');
        button.innerHTML = '<svg class="copy-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"></polyline></svg>'
            + (hasText ? '<span class="btn-text"></span>' : '');
        if (hasText) {
            button.querySelector('.btn-text').textContent = l10n.copied || 'Copied!';
        }
        button._dapfforwcCopyTimer = setTimeout(() => {
            button.classList.remove('copied');
            button.innerHTML = originalHtml;
        }, 2000);
    }).catch(() => {
        alert(l10n.copyFailed || 'Failed to copy. Please select and copy manually.');
    });
}


// SEO page: permalink prefix list (See More, and prefixes that only apply with "Use Attribute Type in Permalinks").
document.addEventListener('DOMContentLoaded', function () {
    const prefixList = document.querySelector('.attribute_prefix_list');
    if (!prefixList) {
        return;
    }
    const prefixContainer = prefixList.querySelector('.prefix_list_container');
    const seeMoreBtn = document.getElementById('dapfforwc_see_more_btn');
    const infoMessage = document.querySelector('.dapfforwc-info-message');
    const useAttributeTypeCheckbox = document.querySelector('input[type="checkbox"][name$="[use_attribute_type_in_permalinks]"]');

    if (seeMoreBtn && prefixContainer) {
        const expandPrefixList = function () {
            prefixContainer.classList.add('is-expanded');
            seeMoreBtn.setAttribute('aria-expanded', 'true');
            seeMoreBtn.style.display = 'none';
        };
        seeMoreBtn.addEventListener('click', function () {
            expandPrefixList();
            // Keep keyboard focus in the list instead of losing it with the hidden button.
            const firstField = prefixContainer.querySelector('input:not([type="hidden"]), select, textarea');
            if (firstField) {
                firstField.focus();
            }
        });
        // Fields below the collapsed height are still in the tab order. The browser scrolls the clipped box to
        // show a focused hidden field; expand the list instead so it is shown in place.
        prefixContainer.addEventListener('focusin', function () {
            setTimeout(function () {
                if (seeMoreBtn.getAttribute('aria-expanded') !== 'true' && prefixContainer.scrollTop > 0) {
                    expandPrefixList();
                    prefixContainer.scrollTop = 0;
                }
            }, 0);
        });
    }

    function syncAttributeTypePrefixes() {
        const usesAttributeType = !useAttributeTypeCheckbox || useAttributeTypeCheckbox.checked;
        prefixList.querySelectorAll('[data-attribute-type-only="1"]').forEach(function (group) {
            group.style.display = usesAttributeType ? '' : 'none';
        });
        if (infoMessage) {
            infoMessage.style.display = usesAttributeType ? 'none' : 'block';
        }
    }

    syncAttributeTypePrefixes();
    if (useAttributeTypeCheckbox) {
        useAttributeTypeCheckbox.addEventListener('change', syncAttributeTypePrefixes);
    }
});
